// Generated by scripts/generate_proto_crate.sh - do not edit manually

use std::fs;
use std::path::Path;

fn main() {
    let proto_dir = Path::new("../../../../sharon-api");

    // Re-run whenever a contract (or this script) changes, so an edited .proto
    // actually reaches the generated types. Without these, Cargo caches the
    // build-script result and the generated code silently keeps describing the
    // OLD contract.
    println!("cargo:rerun-if-changed=build.rs");
    for proto in ["Journal.proto", "File.proto"] {
        let path = proto_dir.join(proto);
        if path.exists() {
            println!("cargo:rerun-if-changed={}", path.display());
        }
    }

    // During `cargo publish`, Cargo extracts the package to a temp directory and builds
    // it to verify. The proto source files won't exist there, but the generated
    // *_proto.rs files are included in the package — build from those.
    //
    // Keyed on the SOURCES being absent, never on the output already existing:
    // "output exists" would skip regeneration forever and is exactly how an
    // edited .proto used to go unnoticed.
    if !proto_dir.join("File.proto").exists() {
        println!("cargo:warning=proto sources not found at {} - using the generated files as-is", proto_dir.display());
        return;
    }

    let out_dir = "src";

    // Generate Journal.proto for ninja storage
    protobuf_codegen::Codegen::new()
        .pure()
        .out_dir(out_dir)
        .input("../../../../sharon-api/Journal.proto")
        .include("../../../../sharon-api")
        .customize(
            protobuf_codegen::Customize::default()
                .gen_mod_rs(false)
        )
        .run_from_script();

    // Rename Journal.rs to journal_proto.rs
    let src = Path::new(out_dir).join("Journal.rs");
    let dst = Path::new(out_dir).join("journal_proto.rs");
    if src.exists() {
        fs::rename(&src, &dst).expect("Failed to rename Journal.rs to journal_proto.rs");
    }

    // Generate File.proto for P2P protocol
    protobuf_codegen::Codegen::new()
        .pure()
        .out_dir(out_dir)
        .input("../../../../sharon-api/File.proto")
        .include("../../../../sharon-api")
        .customize(
            protobuf_codegen::Customize::default()
                .gen_mod_rs(false)
        )
        .run_from_script();

    // Rename File.rs to file_proto.rs
    let src = Path::new(out_dir).join("File.rs");
    let dst = Path::new(out_dir).join("file_proto.rs");
    if src.exists() {
        fs::rename(&src, &dst).expect("Failed to rename File.rs to file_proto.rs");
    }
}
